<?php
/**
 * Portfolio Seeder — Experiences Srl
 * 
 * HOW TO USE:
 * 1. Upload this file to your WordPress root folder (same level as wp-config.php)
 * 2. Visit: https://your-domain.com/seed-portfolio.php
 * 3. DELETE this file immediately after running it
 *
 * This script creates all 8 portfolio posts with images and meta fields.
 * Safe to run multiple times — checks for existing posts before creating.
 */

// Load WordPress
define( 'SHORTINIT', false );
require_once __DIR__ . '/wp-load.php';

// Security: only allow logged-in admins
if ( ! current_user_can( 'manage_options' ) ) {
    wp_die( 'Access denied. You must be logged in as admin.' );
}

echo '<style>body{font-family:sans-serif;max-width:700px;margin:40px auto;padding:20px;}
.ok{color:#0D7C7C;font-weight:bold;} .skip{color:#888;} .err{color:#c00;}</style>';
echo '<h1>Experiences Srl — Portfolio Seeder</h1>';

$sites = [
    [
        'title'    => 'Accoglienza FMA',
        'url'      => 'https://www.accoglienzafma.com',
        'category' => 'Hospitality & Booking',
        'order'    => 1,
        'img_b64'  => '',
        'img_name' => 'accoglienza.jpg',
    ],
    [
        'title'    => 'Villa Crawford',
        'url'      => 'https://www.villacrawford.it',
        'category' => 'Luxury Villa Retreat',
        'order'    => 2,
        'img_b64'  => '',
        'img_name' => 'villa_crawford.jpg',
    ],
    [
        'title'    => 'Villa Tiberiade',
        'url'      => 'https://www.villatiberiade.com',
        'category' => 'Villa & Experience',
        'order'    => 3,
        'img_b64'  => '',
        'img_name' => 'villa_tiberiade.jpg',
    ],
    [
        'title'    => 'CRT San Giorgio',
        'url'      => 'https://www.crtsangiorgio.it',
        'category' => 'Medical Center',
        'order'    => 4,
        'img_b64'  => '',
        'img_name' => 'crt_sangiorgio.jpg',
    ],
    [
        'title'    => 'Vesuvio Express',
        'url'      => 'https://www.vesuvioexpress.it',
        'category' => 'Transport & Tourism',
        'order'    => 5,
        'img_b64'  => '',
        'img_name' => 'vesuvio.jpg',
    ],
    [
        'title'    => 'GioForm',
        'url'      => 'https://www.gio-form.it',
        'category' => 'Education & Training',
        'order'    => 6,
        'img_b64'  => '',
        'img_name' => 'gioform.jpg',
    ],
    [
        'title'    => 'Museo dei Pellegrini',
        'url'      => 'https://museodeipellegrini.it',
        'category' => 'Cultural Heritage',
        'order'    => 7,
        'img_b64'  => '',
        'img_name' => 'museo.jpg',
    ],
    [
        'title'    => 'Arci Confraternita dei Pellegrini',
        'url'      => 'https://arciconfraternitapellegrini.net',
        'category' => 'Associazione Culturale',
        'order'    => 8,
        'img_b64'  => '',
        'img_name' => 'arci.jpg',
    ],
];

$created = 0;
$skipped = 0;

foreach ( $sites as $site ) {

    // Check if already exists
    $existing = get_posts([
        'post_type'   => 'portfolio_site',
        'title'       => $site['title'],
        'post_status' => 'any',
        'numberposts' => 1,
    ]);

    if ( $existing ) {
        echo "<p class=\'skip\'>⏭ Skipped (exists): <strong>{$site['title']}</strong></p>";
        $skipped++;
        continue;
    }

    // Create the post
    $post_id = wp_insert_post([
        'post_title'   => $site['title'],
        'post_type'    => 'portfolio_site',
        'post_status'  => 'publish',
        'menu_order'   => $site['order'],
    ]);

    if ( is_wp_error( $post_id ) ) {
        echo "<p class=\'err\'>❌ Error: {$site['title']} — " . $post_id->get_error_message() . "</p>";
        continue;
    }

    // Save meta fields
    update_post_meta( $post_id, 'site_url',      $site['url'] );
    update_post_meta( $post_id, 'site_category', $site['category'] );

    // Upload image from base64
    $img_data  = base64_decode( $site['img_b64'] );
    $upload    = wp_upload_bits( $site['img_name'], null, $img_data );

    if ( ! $upload['error'] ) {
        $wp_filetype = wp_check_filetype( $site['img_name'], null );
        $attachment  = [
            'post_mime_type' => $wp_filetype['type'],
            'post_title'     => sanitize_file_name( $site['img_name'] ),
            'post_content'   => '',
            'post_status'    => 'inherit',
        ];
        $attach_id = wp_insert_attachment( $attachment, $upload['file'], $post_id );
        require_once ABSPATH . 'wp-admin/includes/image.php';
        $attach_data = wp_generate_attachment_metadata( $attach_id, $upload['file'] );
        wp_update_attachment_metadata( $attach_id, $attach_data );
        set_post_thumbnail( $post_id, $attach_id );
        echo "<p class=\'ok\'>✅ Created: <strong>{$site['title']}</strong> — <a href=\'{$site['url']}\' target=\'_blank\'>{$site['url']}</a></p>";
    } else {
        echo "<p class=\'err\'>⚠ Post created but image failed: {$site['title']} — {$upload['error']}</p>";
    }

    $created++;
}

echo "<hr><h2>Done! Created: $created · Skipped: $skipped</h2>";
echo "<p style=\'color:#c00;font-weight:bold;\'>⚠️ DELETE this file from your server now!</p>";
echo "<p><a href='" . admin_url('edit.php?post_type=portfolio_site') . "'>→ View Portfolio in Dashboard</a></p>";
?>
